callGraph.callee:
runs
      .map((run) => ({
        ...run,
        expectedLegacyStatus: this.expectedLegacyStatus(
          run.lifecycleStatus as AgentLifecycleStatus,
        ),
      }))
      .filter

this.publishPending()
      .catch((error) => {
        this.logger.error(
          'AgentRun outbox scan failed',
          error instanceof Error ? error.message : String(error),
        );
      })
      .finally

this.scan(now)
      .catch((error) => {
        this.logger.error(
          'AgentRun recovery scan failed',
          error instanceof Error ? error.message : String(error),
        );
      })
      .finally

this.reconcileMissingJobs()
      .catch(() => {
        this.logger.error('Agent-control resume reconciliation scan failed');
      })
      .finally
